def handle(args, state, ds):
    report = ds.consistency_report()
    if report.get('pending', 0) == 0:
        return {'status': 'complete'}
    return {'status': 'in_progress', 'remaining': report.get('pending', 0)}

def handle(args, state, ds):
    status = ds.sync_status()
    if not status.get('drift', True):
        return {'status': 'synced'}
    return {'status': 'syncing', 'detail': status.get('detail', '')}

def handle(args, state, ds):
    report = ds.sync_status()
    if not report.get("drift", True):
        return {"status": "synced", "detail": "workspace is fully synced"}
    return {"status": "syncing", "pending_changes": report.get("pending", 0)}

def handle(args, state, ds):
    report = ds.consistency_report()
    if report.get("pending", 1) == 0:
        return {"status": "complete", "remaining": 0}
    return {"status": "in_progress", "pending": report.get("pending", 0)}
